function LeadReportSelect({ value, options, onChange, ariaLabel }) {
  const [isOpen, setIsOpen] = useState(false)
  const containerRef = useRef(null)
  const selectedOption = options.find((option) => String(option.value) === String(value)) || options[0]

  useEffect(() => {
    if (!isOpen) return undefined
    const closeOnOutsideClick = (event) => {
      if (!containerRef.current?.contains(event.target)) setIsOpen(false)
    }
    const closeOnEscape = (event) => {
      if (event.key === 'Escape') setIsOpen(false)
    }
    document.addEventListener('pointerdown', closeOnOutsideClick)
    document.addEventListener('keydown', closeOnEscape)
    return () => {
      document.removeEventListener('pointerdown', closeOnOutsideClick)
      document.removeEventListener('keydown', closeOnEscape)
    }
  }, [isOpen])

  return <div ref={containerRef} className={`lead-report-select ${isOpen ? 'is-open' : ''}`.trim()}><button type="button" className="lead-report-select-trigger" aria-label={ariaLabel} aria-expanded={isOpen} onClick={() => setIsOpen((current) => !current)}><span>{selectedOption?.label || 'Select'}</span><ChevronDown size={16} strokeWidth={2.2} aria-hidden="true" /></button>{isOpen ? <div className="lead-report-select-menu" role="listbox" aria-label={ariaLabel}>{options.map((option) => <button key={option.value} type="button" role="option" aria-selected={String(option.value) === String(value)} className={`lead-report-select-option ${String(option.value) === String(value) ? 'is-selected' : ''}`.trim()} onClick={() => { onChange(option.value); setIsOpen(false) }}>{option.label}</button>)}</div> : null}</div>
}
